    "id": "EX-S7-05",
    "objectiveId": "EX-S7-05",
    "objectiveName": "AWS WAF: WAF placement: edge-scope ACL for true client IP rate limits plus secret origin header to block ALB bypass",
    "variant": 1,
    "domain": "Secure Architectures",
