    "id": "EX-S7-06",
    "objectiveId": "EX-S7-06",
    "objectiveName": "Amazon API Gateway: Replace shared API keys with IAM SigV4 and resource-scoped execute-api:Invoke for service-to-service calls",
    "variant": 1,
    "domain": "Secure Architectures",
