    "id": "EX-R4-10",
    "objectiveId": "EX-R4-10",
    "objectiveName": "Amazon SQS: FIFO dedup's 5-minute window versus durable application idempotency keys for retries arriving hours later.",
    "variant": 1,
    "domain": "Resilient Architectures",
